import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"Prérequis","description":"","frontmatter":{"title":"Prérequis","docId":"user.start.requirements","translationKey":"user.start.requirements","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"c68c149552a943cf0f03393c5dac91bd62abf9c50f791d7b0757599754f4804e","translationRevision":"ee008aeff5df0b3917848ed29fc346703f1984d672c0fae300f902205fd724bd","order":10},"headers":[],"relativePath":"fr/user/requirements.md","filePath":"fr/user/requirements.md","lastUpdated":1794611623000}'),r={name:"fr/user/requirements.md"};function o(s,e,l,u,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="requirements" tabindex="-1">Prérequis <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Prérequis {#requirements}&quot;">​</a></h1><h2 id="goal" tabindex="-1">Objectif <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Objectif {#goal}&quot;">​</a></h2><p>Choisir un paquet de bureau pris en charge et identifier les services nécessaires à votre usage avant l’installation.</p><h2 id="what-you-need" tabindex="-1">Ce dont vous avez besoin <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;Ce dont vous avez besoin {#what-you-need}&quot;">​</a></h2><ul><li>Un ordinateur Windows x86_64 ou Linux x86_64 pour les paquets de bureau publiés. Le processus de publication actuel compile ces deux cibles. Il ne publie ni version de bureau macOS ni APK Android.</li><li>Une session graphique fonctionnelle. Windows nécessite le runtime WebView2 de Microsoft. Linux nécessite un environnement GTK/WebKitGTK compatible ; le DEB déclare ses paquets d’exécution et l’AppImage inclut des utilitaires multimédias vérifiés.</li><li>Un accès réseau à TikTok pour une véritable connexion LIVE. Une salle hors ligne, une session invitée expirée ou une limitation du service distant ne se corrigent pas en modifiant une automatisation.</li><li>Un espace de stockage hors du répertoire d’installation pour les données SQLite, plugins et journaux. L’application détermine un répertoire de données par utilisateur ; déplacer l’exécutable ne déplace pas ces données.</li></ul><p>Un compte Cloud est nécessaire pour les opérations de catalogue ou de collaboration liées au compte, pas pour tous les éditeurs locaux. OBS n’est nécessaire que pour afficher un widget dans une diffusion. Les intégrations audio/TTS peuvent nécessiter un plugin installé séparément et son propre fournisseur ou service.</p><h2 id="check-the-environment" tabindex="-1">Vérifier l’environnement <a class="header-anchor" href="#check-the-environment" aria-label="Permalink to &quot;Vérifier l’environnement {#check-the-environment}&quot;">​</a></h2><ol><li>Choisissez le paquet correspondant à votre système d’exploitation et à l’architecture x86_64.</li><li>Sous Windows, installez WebView2 si l’installateur signale son absence. Sous Linux, installez les bibliothèques d’exécution manquantes avec le gestionnaire de paquets de votre distribution.</li><li>Vérifiez que la fenêtre de l’application s’ouvre avant de vous connecter à TikTok ou d’ajouter des plugins.</li><li>Poursuivez avec l’<a href="./installation.html">installation</a>, puis <a href="./first-live.html">votre premier LIVE</a>.</li></ol><h2 id="expected-result" tabindex="-1">Résultat attendu <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Résultat attendu {#expected-result}&quot;">​</a></h2><p>L’application s’ouvre et sa navigation principale fonctionne hors ligne. Les intégrations facultatives peuvent rester indisponibles tant que leur plugin ou la capacité correspondante de l’hôte manque.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>En cas de fenêtre vide ou de fermeture précoce, recueillez les diagnostics de démarrage et la version exacte du paquet. AppImage et DEB sont deux formats d’installation différents ; aucun n’est un exécutable Android. Consultez le <a href="./termux.html">périmètre Termux et sans interface graphique</a> pour cet environnement. La compilation depuis les sources comporte des prérequis supplémentaires dans le guide de développement.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Si aucune fenêtre ne s’ouvre, consultez le journal natif <code>tiktools.log</code> (<code>controller.log</code> en mode contrôleur) : Windows <code>%LOCALAPPDATA%/TikTools/logs</code>, Linux <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code>, sauf modification par <code>TIKTOOLS_HOME</code> ou <code>TIKTOOLS_LOG_DIR</code>. L’initialisation peut échouer avant la création du fichier. Conservez l’erreur du terminal et consultez <a href="./preferences/troubleshooting.html#operational-details">conservation et confidentialité</a> avant partage.</p>',14)])])}const h=a(r,[["render",o]]);export{f as __pageData,h as default};
